/*
一括承認用
WFの遷移時に子アイテムのLCを遷移する
*/
Innovator inn = this.getInnovator();

//引数取得
string destination = this.getProperty("destination");
string sourceId = this.getProperty("sourceId");

//リレーション取得
var promotionItems = new List<Item>();
using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
{
    Item mqs = inn.newItem("h4_AppWFGr4DATFormat DATFormat", "get");
    mqs.setProperty("source_id", sourceId);
    Item mqr = mqs.apply();

    //リレーションからアイテムを取得
    for (int i = 0; i<mqr.getItemCount(); i++) {
        Item rel = mqr.getItemByIndex(i);
        Item targetItem = rel.getRelatedItem();
        // 遷移元と遷移先が同じ場合遷移させない
        if(targetItem.getProperty("state","") == destination)
        {
            continue;
        }
    
        promotionItems.Add(targetItem);
    }

}

//プロモート
foreach (Item itm in promotionItems)
{
    using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Aras PLM")))
    {    
        itm.promote(destination,"Promote message");  
    }
}

return this;

}
private void dummy()
{
